style.css:
@-moz-document url-prefix("http"), url-prefix("https") {
/* ======== KLEUREN ======== */
  :root {
    --p2-bg: #1a1a1a;
    --p2-bg-soft: #202020;
    --p2-panel: #262626;
    --p2-border: #3a3a3a;
    --p2-text: #f2f2f2;
    --p2-muted: #bdbdbd;
    --p2-blue: #27A7D8;
    --p2-orange: #FF9A00;
    --p2-radius: 4px;
  }

  /* ======== BASIS ======== */
  body {
    background: var(--p2-bg) !important;
    color: var(--p2-text) !important;
    font-family: "Segoe UI", "Roboto", sans-serif !important;
  }

  /* ======== TITELS ======== */
  h1, h2, h3, h4 {
    color: var(--p2-text) !important;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    border-bottom: 2px solid var(--p2-blue);
    padding-bottom: 4px;
  }

  /* ======== LINKS ======== */
  a {
    color: var(--p2-blue) !important;
    text-decoration: none !important;
    font-weight: 500;
  }

  a:hover {
    color: var(--p2-orange) !important;
    text-decoration: underline !important;
  }

  /* ======== PANELS (VEILIG) ======== */
  /* Alleen echte content-blokken, niet ALLES */
  .card, .panel, .module, .content-box, .widget {
    background: var(--p2-panel) !important;
    border: 1px solid var(--p2-border) !important;
    border-radius: var(--p2-radius) !important;
    padding: 10px !important;
  }

  /* ======== KNOPPEN ======== */
  button, .btn, input[type="submit"], input[type="button"] {
    background: var(--p2-blue) !important;
    color: #000 !important;
    border: none !important;
    border-radius: var(--p2-radius) !important;
    padding: 8px 16px !important;
    text-transform: uppercase;
    font-weight: 600;
    cursor: pointer;
    transition: 0.15s ease;
  }

  button:hover, .btn:hover {
    background: var(--p2-orange) !important;
    transform: translateY(-1px);
  }

  /* ======== INPUTS ======== */
  input[type="text"], input[type="password"], textarea, select {
    background: var(--p2-bg-soft) !important;
    color: var(--p2-text) !important;
    border: 1px solid var(--p2-border) !important;
    border-radius: var(--p2-radius) !important;
    padding: 6px !important;
  }

  ::placeholder {
    color: var(--p2-muted) !important;
  }

  /* ======== SCROLLBAR ======== */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: var(--p2-blue);
    border-radius: 0;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: var(--p2-orange);
  }

  /* ======== PORTAL 2 GRID BACKGROUND ======== */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background-image:
      linear-gradient(#222 1px, transparent 1px),
      linear-gradient(90deg, #222 1px, transparent 1px);
    background-size: 80px 80px;
    opacity: 0.15;
    z-index: -1;
  }
}
